/**
 * Spell-shape classifier — Wave 5 / Phase 12 of the CombatManeuverTable
 * fixes plan (`external/holtburger/docs/cmt-fixes-plan-2026-05-26.md`).
 *
 * Resolves a SpellId u32 to `{ school, shape, level }` so the renderer
 * can pick projectile-spawn patterns based on spell metadata. The cast
 * wind-up motion is uniform per retail; only the projectile pattern
 * differs by shape.
 *
 * ## Why this helper exists
 *
 * The acpedia wiki (cross-referenced in
 * `external/holtburger/docs/acpedia-combat-research-2026-05-26.md`
 * §War Magic + §Void Magic) documents two distinct projectile-shape
 * vocabularies for the two damage-dealing magic schools:
 *
 *   - **War Magic — 6 shapes:** Arc, Ring, Wall, Bolt, Volley, Blast.
 *     The 7th, **Streak**, was added/tuned in the Slumbering Giant
 *     patch as rapid-fire same-projectile (acpedia text: "streak rate-
 *     of-fire + blast/volley damage tuned"). The catalog has 53 War
 *     Streak spells, so we expose Streak in the War set even though
 *     the wiki's lead lists 6.
 *
 *   - **Void Magic — 5 shapes:** Arc, Ring, Bolt, Streak, Blast.
 *     No Wall, no Volley. Void adds DoT (Corruption, Corrosion,
 *     Festering Curse) and stat-debuff (Weakening Curse) variants
 *     that have NO projectile shape — they're handled as `Self`.
 *
 * The renderer-side union is 7 projectile shapes + 1 non-projectile:
 * Bolt, Arc, Streak, Volley, Wall, Ring, Blast, Self.
 *
 * ## Cast-motion uniformity
 *
 * Per `acpedia-combat-research-2026-05-26.md` §War Magic:
 *
 * > "We should expect the cast animation to be the same regardless of
 * > shape — the *projectile pattern* is the differentiator, not the
 * > wind-up. The CMT does have magic-stance rows but no per-spell-
 * > shape variation that we've seen; the spell shape is driven by
 * > `SpellId`-on-wire, not by stance."
 *
 * So the renderer should NOT consult `classifySpell` to pick a swing
 * motion — `MagicCombat` stance + the existing `Player_Combat` /
 * `CastSpell` path already covers that. This classifier is for the
 * **projectile-spawner** layer: given the SpellId that fired, look up
 * the shape and spawn the right number/pattern of projectiles.
 *
 * ## Data source
 *
 * `data/spell-shapes.json` is generated by
 * `scripts/gen-spell-shapes.cjs` from the existing committed catalog
 * `data/spells-catalog.json` (which the Python pipeline at
 * `scripts/build_spells_catalog.py` builds from LSD-Partial). See the
 * generator's header for the full classification rule set.
 *
 * School values match ACE's `MagicSchool` enum:
 * `~/ace-server/Source/ACE.Entity/Enum/MagicSchool.cs` —
 * `None=0, WarMagic=1, LifeMagic=2, ItemEnchantment=3,
 * CreatureEnchantment=4, VoidMagic=5`.
 *
 * ## Hard scope (Phase 12)
 *
 * This module ships the helper + data only. The renderer-side wiring
 * (picking.js / spell-picker / projectile-spawner) is a separate
 * follow-on. Don't import this from `picking.js`, `index.html`, or
 * `plugins/spellbook.js` yet.
 *
 * Authored 2026-05-26 for CMT fixes Wave 5 Phase 12 (Agent K).
 */

/**
 * Spell schools — ACE `MagicSchool` enum verbatim.
 *
 * @type {Readonly<{
 *   None: 0, War: 1, Life: 2, Item: 3, Creature: 4, Void: 5
 * }>}
 */
export const SPELL_SCHOOL = Object.freeze({
  None:     0,
  War:      1,
  Life:     2,
  Item:     3,
  Creature: 4,
  Void:     5,
});

/**
 * Spell-shape vocabulary — 7-projectile superset + non-projectile
 * `Self` bucket. Values are display strings (the same strings stored
 * in `data/spell-shapes.json`) so callers can do
 * `if (s.shape === SPELL_SHAPE.Bolt) { … }` without an enum-int round
 * trip.
 *
 * Shapes (renderer-side hints):
 *   - **Bolt**   — single projectile, straight-line from caster to target
 *   - **Arc**    — single projectile, parabolic arc to target
 *   - **Streak** — rapid-fire repeating same-projectile, target-locked
 *   - **Volley** — multi-projectile fan, all converging on target
 *                  (includes "rains N down" sky-rain spells)
 *   - **Wall**   — multi-projectile slow-advancing wall toward target
 *                  (also "forward wave-cone from caster")
 *   - **Ring**   — caster-centered AoE ring; N projectiles outward
 *                  from the caster radiating in a circle
 *   - **Blast**  — AoE explosion at the target point
 *   - **Self**   — no projectile pattern; renderer plays cast wind-up
 *                  + a target-side effect overlay only. Covers all
 *                  Life / Item / Creature enchantments AND War / Void
 *                  spells that lack a projectile (DoTs, debuffs,
 *                  "kills the target" procs, fireworks, creature-
 *                  magic-only placeholders, etc.)
 *
 * @type {Readonly<{
 *   Bolt: "Bolt", Arc: "Arc", Streak: "Streak", Volley: "Volley",
 *   Wall: "Wall", Ring: "Ring", Blast: "Blast", Self: "Self"
 * }>}
 */
export const SPELL_SHAPE = Object.freeze({
  Bolt:   "Bolt",
  Arc:    "Arc",
  Streak: "Streak",
  Volley: "Volley",
  Wall:   "Wall",
  Ring:   "Ring",
  Blast:  "Blast",
  Self:   "Self",
});

/**
 * Lazy-loaded shape table — fetched on first `classifySpell` call.
 *
 * Browser deployments serve the JSON from `./data/spell-shapes.json`
 * relative to the page (typical `apps/holtburger-web/` layout). Node-
 * side test runners (e.g. `node test_ac_spell_shape.mjs`) preload the
 * table synchronously via `_loadTableSync()` because they don't have
 * `fetch` in the Node 18 default; the helper exports `_loadTableSync`
 * for that case.
 *
 * The cache is per-process. To force a reload (after regenerating
 * `data/spell-shapes.json`), call `_resetTable()` — exposed for tests.
 *
 * @type {Record<string, {school: number, shape: string, level: number}> | null}
 */
let _shapeTable = null;
let _pendingFetch = null;

const DEFAULT_TABLE_URL = "./data/spell-shapes.json";

/**
 * @internal Browser-side async loader. Called lazily from
 * `classifySpell` if the table isn't preloaded. Caches the in-flight
 * `fetch` so concurrent calls don't double-fetch.
 *
 * @param {string} [url] override the default table URL (e.g. when the
 *   helper is loaded from a CDN with a different base path)
 * @returns {Promise<Record<string, object>>}
 */
async function _loadTableAsync(url) {
  if (_shapeTable) return _shapeTable;
  if (_pendingFetch) return _pendingFetch;
  _pendingFetch = fetch(url || DEFAULT_TABLE_URL, { cache: "force-cache" })
    .then((r) => {
      if (!r.ok) throw new Error(`spell-shapes fetch ${r.status}`);
      return r.json();
    })
    .then((table) => {
      _shapeTable = table;
      _pendingFetch = null;
      return table;
    })
    .catch((err) => {
      _pendingFetch = null;
      throw err;
    });
  return _pendingFetch;
}

/**
 * Synchronously preload the shape table from a JS object — used by
 * Node-side tests that read `data/spell-shapes.json` with `fs.readFile`
 * and want `classifySpell` to be synchronous.
 *
 * @param {Record<string, {school: number, shape: string, level: number}>} table
 * @returns {void}
 */
export function _loadTableSync(table) {
  if (!table || typeof table !== "object") {
    throw new Error("_loadTableSync: table must be a non-null object");
  }
  _shapeTable = table;
  _pendingFetch = null;
}

/**
 * Reset the cached table — for tests that want to verify async loading
 * works.
 *
 * @returns {void}
 */
export function _resetTable() {
  _shapeTable = null;
  _pendingFetch = null;
}

/**
 * Has the table been loaded yet? Browser callers can check this before
 * calling `classifySpell` to decide whether to fall back to a default
 * shape (e.g. `Bolt`) for the first-frame race.
 *
 * @returns {boolean}
 */
export function isShapeTableLoaded() {
  return _shapeTable !== null;
}

/**
 * Classify a spell by its 32-bit SpellId. Returns `{ school, shape,
 * level }` or `null` if the table isn't loaded OR the SpellId is not
 * in the catalog (LSD has 6,266 entries; unknown / homebrew /
 * server-mod spells fall outside that and return `null`).
 *
 * - `school`: `SPELL_SCHOOL` integer (0=None, 1=War, 2=Life,
 *   3=Item, 4=Creature, 5=Void).
 * - `shape`: one of the `SPELL_SHAPE` strings (`Bolt` / `Arc` /
 *   `Streak` / `Volley` / `Wall` / `Ring` / `Blast` / `Self`).
 *   Non-War-Magic / Non-Void-Magic spells are always `Self`; War +
 *   Void spells without a projectile (DoTs, debuffs, etc.) are also
 *   `Self`.
 * - `level`: 1-8 spell tier from the trailing Roman numeral in the
 *   name. Defaults to 1 for spells without a numeral suffix.
 *
 * Browser-side first-call note: the helper lazy-fetches the table on
 * first use. Synchronous callers should preload via `_loadTableSync`
 * (Node tests) or kick a `_loadTableAsync()` at app boot (browser).
 * If `classifySpell` runs before the table is loaded, it returns
 * `null` — callers MUST handle that case (the renderer's fallback
 * should be: assume `Bolt` for unknown spells, since that's the
 * dominant War shape).
 *
 * @param {number | string} spellId — u32 SpellId; numeric or numeric
 *   string. Out-of-range values (NaN, < 0) return `null`.
 * @returns {{ school: number, shape: string, level: number } | null}
 */
export function classifySpell(spellId) {
  if (_shapeTable === null) {
    // Kick the async load but return null synchronously — see
    // function-header note. Callers should preload, but we don't want
    // a single missed first-call to throw.
    if (typeof fetch === "function" && !_pendingFetch) {
      _loadTableAsync().catch(() => { /* swallow; future call retries */ });
    }
    return null;
  }
  // Normalize SpellId to a string key. The JSON keys are decimal
  // strings (e.g. "75" for Lightning Bolt I) — same as the catalog
  // and same as ACE's `Spell.Id` integer property serialized.
  let key;
  if (typeof spellId === "number") {
    if (!Number.isFinite(spellId) || spellId < 0) return null;
    key = String(spellId | 0);  // u32 truncate
  } else if (typeof spellId === "string") {
    // Accept "0x4B" hex prefix as well as plain decimal — the wire
    // never sends hex, but JS callers may pass either. ACE's u32 is
    // signed-positive only.
    const parsed = spellId.startsWith("0x") || spellId.startsWith("0X")
      ? parseInt(spellId, 16)
      : parseInt(spellId, 10);
    if (!Number.isFinite(parsed) || parsed < 0) return null;
    key = String(parsed | 0);
  } else {
    return null;
  }
  const entry = _shapeTable[key];
  if (!entry) return null;
  // The table values are already shape strings + school ints + level
  // ints, but harden against stale tables / partial fields. The
  // generator validates these on emit, so this is defensive only.
  return {
    school: entry.school | 0,
    shape: entry.shape || SPELL_SHAPE.Self,
    level: entry.level | 0 || 1,
  };
}

